const viewport = document.querySelector('meta[name="viewport"]');
if (!viewport) return false;
const content = viewport.getAttribute('content') || '';
return /width\s*=\s*device-width/i.test(content) && /initial-scale\s*=\s*1(?:\.0)?/i.test(content);

const container = document.querySelector('.container');
if (!container || getComputedStyle(container).maxWidth === 'none') return false;
// computed margins are always pixels, so check the CSS rule itself for auto margins
const rules = [...document.styleSheets].flatMap((sheet) => [...sheet.cssRules]);
return rules.some((rule) => {
  if (!rule.selectorText || !rule.selectorText.split(',').map((s) => s.trim()).includes('.container')) return false;
  const st = rule.style;
  return (st.marginLeft === 'auto' && st.marginRight === 'auto') || (st.marginInlineStart === 'auto' && st.marginInlineEnd === 'auto');
});

const hasMinWidthMedia = [...document.styleSheets].some(sheet => {
  try {
    return [...sheet.cssRules].some(rule => rule instanceof CSSMediaRule && /min-width\s*:/i.test(rule.conditionText || rule.media.mediaText));
  } catch (error) {
    return false;
  }
});
return hasMinWidthMedia;

let baseRuleFound = false;
let responsiveRuleFound = false;
for (const sheet of document.styleSheets) {
  let rules;
  try { rules = [...sheet.cssRules]; } catch (error) { continue; }
  for (const rule of rules) {
    if (rule instanceof CSSStyleRule && rule.selectorText === '.columns') {
      baseRuleFound = true;
      const display = rule.style.display;
      const template = rule.style.getPropertyValue('grid-template-columns');
      if (display === 'grid' || display === 'flex' || !template || !/\S+\s+\S+/.test(template)) {
        if (display !== 'grid' && display !== 'flex' && template && /\S+\s+\S+/.test(template)) return false;
      }
    }
    if (rule instanceof CSSMediaRule && /min-width\s*:/i.test(rule.conditionText || rule.media.mediaText)) {
      for (const nested of rule.cssRules) {
        if (nested instanceof CSSStyleRule && nested.selectorText === '.columns' && (nested.style.display === 'grid' || nested.style.display === 'flex')) {
          responsiveRuleFound = true;
        }
      }
    }
  }
}
return baseRuleFound && responsiveRuleFound;
